"""Pak Studies XII PDF53 (spread): printed pp.95–96 — Ch.5 local governments (2013): village/neighbourhood councils and their responsibilities."""
from class12_book_common import Book, Builder

BOOK = Book('pak')
t = Builder()
def P(*v): t.p(*v)
def H(*v): t.h(*v)
P('The Act of 2005 was enforced with some amendments. Now new local governments have been formed, whose details are as follows.',
  '2005ء کے ایکٹ کو بعض ترامیم کے ساتھ نافذ کیا گیا۔ اب نئی مقامی حکومتیں تشکیل دی گئی ہیں جن کی تفصیل مندرجہ ذیل ہے۔',
  'د ۲۰۰۵ز قانون د ځینو تعدیلاتو سره پلی شو. اوس نوي سیمه‌ییز حکومتونه جوړ شوي چې جزییات یې دا دي:')
H('Local governments (2013)', 'مقامی حکومتیں (2013ء)', 'سیمه‌ییز حکومتونه (۲۰۱۳ز)')
P('According to the Local Governments Act 2013, the provincial assembly completed the first phase of local-body elections on 30 May 2015, under which local governments of three levels were formed.',
  'صوبائی اسمبلی نے مقامی حکومتوں کے ایکٹ 2013ء کے مطابق 30 مئی 2015ء کو بلدیاتی انتخابات کا پہلا مرحلہ مکمل کیا جس کے تحت تین سطح کی مقامی حکومتیں بنیں۔',
  'ولایتي اسمبلۍ د سیمه‌ییزو حکومتونو د قانون ۲۰۱۳ز سره سم د ۲۰۱۵ز د مۍ په ۳۰مه د ښاروالیو ټاکنو لومړی پړاو بشپړ کړ، چې له مخې یې په درې کچو سیمه‌ییز حکومتونه جوړ شول:')
t.group('lines', [('1. Village/Neighbourhood Council', '1۔ دیہی/محلہ کونسل', '۱. د کلي/محلې شورا'), ('2. Tehsil/Town Council', '2۔ تحصیل/ٹاؤن کونسل', '۲. د تحصیل/ښارګوټي شورا'),
                  ('3. District government/District Council', '3۔ ضلعی حکومت/ضلع کونسل', '۳. د ولسوالۍ حکومت/د ولسوالۍ شورا')])
H('Village/Neighbourhood Council', 'دیہی/محلہ کونسل', 'د کلي/محلې شورا')
P('The basic unit of this system of local governments is the Village Council for rural areas and the Neighbourhood Council for urban areas. The Village and Neighbourhood Council consists of 10 to 15 members. Five to ten members, determined on the basis of population, are elected on general seats, while two seats are reserved for women and one each for labourer/peasant, youth and non-Muslims. The general councillor receiving the most votes is called the Nazim and the one receiving the second most votes the Naib Nazim. These elections are held directly on a non-party basis. In the whole province about three thousand five hundred Village and Neighbourhood Councils have been established. In every council seats have been reserved for women, labourers/peasants, minorities and youth, through which it has been ensured that all classes of society are given effective representation. The basic responsibilities of the Village and Neighbourhood Councils are these.',
  'مقامی حکومتوں کے اس نظام کی بنیادی اکائی دیہی علاقوں کے لیے دیہی کونسل اور شہری علاقوں کے لیے محلہ کونسل ہے۔ دیہی اور محلہ کونسل 10 سے 15 ارکان پر مشتمل ہوتی ہے۔ آبادی کی بنیاد پر متعین کردہ پانچ سے دس ارکان جنرل نشستوں پر منتخب ہوتے ہیں جبکہ خواتین کی دو، مزدور/کسان، نوجوان اور غیر مسلموں کے ایک ایک نشست مختص ہے۔ جنرل کونسلر میں سب سے زیادہ ووٹ لینے والا ناظم اور دوسرے نمبر پر زیادہ ووٹ لینے والا نائب ناظم کہلاتا ہے۔ یہ انتخابات غیر جماعتی بنیادوں پر بلاواسطہ ہوتے ہیں۔ پورے صوبے میں تقریباً تین ہزار پانچ سو دیہی اور محلہ کونسلیں قائم کی گئی ہیں۔ ہر کونسل میں خواتین، مزدوروں/کسانوں، اقلیتوں اور نوجوانوں کے لیے نشستیں مخصوص کی گئی ہیں جس کی وجہ سے یہ یقینی بنایا گیا ہے کہ معاشرے کے تمام طبقات کو مؤثر نمائندگی دی جائے۔ دیہی اور محلہ کونسلوں کی بنیادی ذمہ داریاں یہ ہیں۔',
  'د سیمه‌ییزو حکومتونو د دې نظام بنسټیز واحد د کلیوالو سیمو لپاره د کلي شورا او د ښاري سیمو لپاره د محلې شورا ده. د کلي او محلې شورا له ۱۰ تر ۱۵ غړو جوړه وي. د نفوس پر بنسټ ټاکل شوي له پنځو تر لسو غړي په عمومي څوکیو ټاکل کېږي، په داسې حال کې چې د ښځو دوه، او کارګر/بزګر، ځوان او غیر مسلمانانو ته یوه یوه څوکۍ ځانګړې ده. په عمومي غړو کې تر ټولو ډېرې رایې اخیستونکی ناظم او په دویم نمبر ډېرې رایې اخیستونکی مرستیال ناظم بلل کېږي. دا ټاکنې پر غیر ګوندي بنسټ مستقیمې کېږي. په ټول ولایت کې شاوخوا درې زره پنځه سوه د کلي او محلې شوراګانې جوړې شوې. په هره شورا کې د ښځو، کارګرانو/بزګرانو، لږکیو او ځوانانو لپاره څوکۍ ځانګړې شوې، چې له امله یې ډاډ ورکړل شوی چې د ټولنې ټولو طبقو ته اغېزمن استازیتوب ورکړل شي. د کلي او محلې شوراګانو بنسټیز مسؤولیتونه دا دي:')
H('Responsibilities of the Village/Neighbourhood Council', 'دیہی/محلہ کونسل کی ذمہ داریاں', 'د کلي/محلې شورا مسؤولیتونه')
t.group('lines', [
 ('1. Supervision of the performance of government offices, so that improvement is brought about in the provision of government services to the people.', '1۔ سرکاری دفاتر کی کارکردگی کی نگرانی تاکہ عوام کو سرکاری خدمات کی فراہمی میں بہتری لائی جائے۔', '۱. د دولتي دفترونو د کارکردګۍ څارنه، څو خلکو ته د دولتي خدماتو په وړاندې کولو کې ښه والی راشي.'),
 ('2. Peaceful settlement of disputes through arbitration, so that differences in society can be ended.', '2۔ ثالثی کے ذریعے تنازعات کا پُرامن حل تاکہ معاشرے میں اختلافات کا خاتمہ ہو سکے۔', '۲. د منځګړیتوب له لارې د شخړو سوله‌ییز حل، څو په ټولنه کې اختلافات پای ته ورسېږي.'),
 ('3. Registration of births, deaths and marriages, so that better planning for welfare can be done.', '3۔ پیدائش، اموات اور نکاح کی رجسٹریشن تاکہ فلاح و بہبود کی بہتر منصوبہ بندی ہو سکے۔', '۳. د زېږونونو، مړینو او نکاحونو ثبت، څو د هوساینې ښه پلان جوړ شي.'),
 ('4. At the village and neighbourhood level, provision of clean water, sanitation, drainage, paving of streets, care of social and collective places, and construction and repair of playgrounds, so that health care and healthy activities can be arranged at the local level.', '4۔ گاؤں اور محلے کی سطح پر صاف پانی کی فراہمی، صفائی، نکاسیٔ آب، گلیوں کی پختگی، سماجی اور اجتماعی مقامات کی دیکھ بھال اور کھیلوں کے لیے میدانوں کی تعمیر و مرمت تاکہ مقامی سطح پر حفظانِ صحت اور صحت مند سرگرمیوں کا انتظام ہو سکے۔', '۴. د کلي او محلې په کچه د پاکو اوبو برابرول، صفايي، د اوبو ایستل، د کوڅو پخول، د ټولنیزو او ګډو ځایونو پاملرنه او د لوبو د ډګرونو جوړول او ترمیم، څو په سیمه‌ییزه کچه د روغتیا ساتنه او روغ فعالیتونه ترتیب شي.'),
 ('5. Organising ordinary people for collective welfare, so that they can take part in the construction and repair of streets, lanes and roads and in cleaning canals.', '5۔ عام لوگوں کو اجتماعی فلاح و بہبود کے لیے منظم کرنا تاکہ گلیوں، کوچوں اور شاہراہوں کی تعمیر و مرمت اور انہار کی صفائی میں حصہ لے سکیں۔', '۵. عام خلک د ټولیزې هوساینې لپاره تنظیمول، څو د کوڅو، لارو او سړکونو په جوړولو او ترمیم او د ویالو په پاکولو کې ګډون وکړي.'),
 ('6. Arranging watchmen at the street and neighbourhood level, so that a sense of security can be created among people.', '6۔ گلی اور محلے کی سطح پر چوکیداروں کا انتظام تاکہ لوگوں میں تحفظ کا احساس پیدا ہو سکے۔', '۶. د کوڅې او محلې په کچه د چوکیدارانو ترتیب، څو په خلکو کې د امنیت احساس پیدا شي.'),
 ('7. Selection of an accounts committee at the council level, so that regular accounts of the expenditure of government money can be kept.', '7۔ کونسل کی سطح پر ایک اکاؤنٹس کمیٹی کا انتخاب تاکہ سرکاری رقم کے خرچ کا باقاعدہ حساب کتاب کیا جا سکے۔', '۷. د شورا په کچه د حساب کمېټې ټاکل، څو د دولتي پیسو د لګښت منظم حساب وساتل شي.'),
 ('8. Arranging the provision of resources for the disabled, the poor and the destitute, so that their difficulties and hardships can be removed.', '8۔ معذوروں، غریبوں اور ناداروں کے لیے وسائل کی فراہمی کا انتظام تاکہ ان کے مشکلات اور تکالیف کا ازالہ ہو سکے۔', '۸. د معلولینو، بېوزلو او بې‌وزلو لپاره د سرچینو د برابرولو ترتیب، څو د هغوی ستونزې او تکلیفونه لرې شي.'),
])
